import { readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { describe, expect, it } from "vitest";
import { normalizePhone } from "@/lib/appointments/phone";

const CRM_CASES = join(process.cwd(), "supabase/tests/customer-crm/phone-cases.json");
const CASES_PATH = join(process.cwd(), "supabase/tests/fitting-import/phone-cases.json");

function buildCases() {
  const crm = JSON.parse(readFileSync(CRM_CASES, "utf8")) as { expected: { phone: string | null }[] };
  return {
    about:
      "Generated by lib/fitting-import/__tests__/phone-e164-agreement.test.ts (UPDATE_SQL_CASES=1). `e164` is " +
      "normalizePhone; supabase/tests/fitting-import/assert-phone.sql requires public.phone_e164 to give the same.",
    expected: crm.expected.map(({ phone }) => ({ phone, e164: normalizePhone(phone) })),
  };
}

describe("normalizePhone and public.phone_e164 run the same fixture", () => {
  it("phone-cases.json holds the TypeScript's answer for every phone", () => {
    const cases = buildCases();
    if (process.env.UPDATE_SQL_CASES) writeFileSync(CASES_PATH, `${JSON.stringify(cases, null, 2)}\n`);
    expect(JSON.parse(readFileSync(CASES_PATH, "utf8"))).toEqual(cases);
  });

  it("covers numbers that normalise and numbers that do not", () => {
    const { expected } = buildCases();
    expect(expected.filter((c) => c.e164).length).toBeGreaterThan(5);
    expect(expected.filter((c) => !c.e164).length).toBeGreaterThan(5);
  });
});
